n.loginUrl:
api = 'https://www.yizhiqc.com/api/';
method = ",{'method':'POST'}";

function log(t){
		java.toast(t);
		java.log(t);
	}


function login(type){

url = api+'person-';

data = JSON.parse(java.ajax(url+'info'+method));
if(data.returnCode!=200){
userInfo=source.getLoginInfoMap()
UNE=userInfo['账号']
PWD=userInfo['密码']


body = 'login?userName='+UNE+'&userPassword='+java.md5Encode(PWD)+'&terminal=2';

url += body+method;


data=JSON.parse(java.ajax(url));
try{
token = data.data.token;
headers = JSON.stringify({token:token});
source.putLoginHeader(headers);
Object.assign($,{
		userId: data.data.userId,
		userName: data.data.pseudonym
	});
setv($);
}catch(err){}

if(type){// 重新签到
	log(data.msg);
	return dailyAttendance();
	}
	return log(data.msg);
}else{
	if(type==undefined)return true;
	return log("正在登录\n\n需要重新登录？\n点击右上角，删除登录头。");
}
}


dailyAttendance=()=>{
url = api+"user-signinTow?operationType=1";
msg = JSON.parse(java.ajax(url)).msg;
if(msg.match(/过期/)){
		log("登录过期，正在重新登录…");
		return login(1);
	}
text = "\n每日签到："+msg;
return log(text);
}


getinfo=()=>{
url = api+"person-info"+method;
data = JSON.parse(java.ajax(url));
if(data.returnCode==200){
	data = data.data;
	text = "正在登录\n昵称："+data.pseudonym+"\n\n纸纸币："+data.userMoney+"\n  代币  ："+data.donationMoney+"\n阅读劵："+data.userReadTicket
}
else{
	text = "登录过期/没有登录";
	}
return log(text);
}






